// English-specific API: daily plans and reading materials generated by the selected local AI CLI.
//
// Once per workday, one CLI run turns the plan frame (js/plan.js), the course material
// (content/) and the training record (data/) into that day's plan and reading material.
// They are frozen in data/plans/<date>.json and data/materials/<date>.json and never
// regenerated or overwritten.
import { readFile, writeFile, mkdir, readdir } from 'node:fs/promises';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { askJson } from '../assets/ai-cli.mjs';
import { TRACK_BY_DAY, TRACK_LABEL, PHASES, GRAMMAR_WEEKS, PAGES, ymd, parseYmd, weekNumber, phaseOf, isWorkday, previousWorkdays } from './js/plan.js';
import { wordsOf, lexiconProfile } from './js/lexicon.js';
import { LESSONS } from './content/grammar.js';
import { LEVELS } from './content/sources.js';
import { PROMPTS } from './content/prompts.js';

const DIR = dirname(fileURLToPath(import.meta.url));
const DATA = join(DIR, 'data');
const PLANS = join(DATA, 'plans');
const MATERIALS = join(DATA, 'materials');
const DATE = /^\d{4}-\d{2}-\d{2}$/;

const inflight = new Map(); // date -> Promise<plan>, so a double click spawns one CLI run

async function readJson(file, fallback) {
  try {
    return JSON.parse(await readFile(file, 'utf8'));
  } catch {
    return fallback;
  }
}
const data = (name, fallback) => readJson(join(DATA, `${name}.json`), fallback);
const planFile = (date) => join(PLANS, `${date}.json`);
const materialFile = (date) => join(MATERIALS, `${date}.json`);

// Write only if the file doesn't exist yet. Returns false if it already did.
async function createOnce(file, obj) {
  await mkdir(dirname(file), { recursive: true });
  try {
    await writeFile(file, JSON.stringify(obj, null, 2) + '\n', { flag: 'wx' });
    return true;
  } catch (e) {
    if (e.code === 'EEXIST') return false;
    throw e;
  }
}

// ---------- context ----------

// Word-count band for the material, by phase/week. Adjusted by the generator from reading results.
function lengthBand(week, phase) {
  if (phase === 1) return week <= 2 ? '150–220 词' : '200–280 词';
  if (phase === 2) return '300–500 词';
  return '500–800 词';
}

async function buildContext(date) {
  const day = parseYmd(date);
  const [settings, checkins, words, reading, journal, reviews, grammar, phases] = await Promise.all([
    data('settings', {}), data('checkins', []), data('words', []), data('reading', []),
    data('journal', []), data('reviews', []), data('grammar', {}), data('phases', {}),
  ]);
  const week = weekNumber(settings.startDate, day);
  const phase = phaseOf(week);
  const track = TRACK_BY_DAY[day.getDay()];

  const recentDays = previousWorkdays(day, 5);
  const byDate = Object.fromEntries(checkins.map((c) => [c.date, c]));
  const recentPlans = [];
  const recentMaterials = [];
  for (const d of recentDays) {
    const p = await readJson(planFile(d), null);
    if (p && recentPlans.length < 3) recentPlans.push({ date: d, focus: p.focus, tasks: p.tasks.map((t) => t.title), done: byDate[d]?.tasks || [], checkedIn: !!byDate[d]?.done });
    const m = await readJson(materialFile(d), null);
    if (m) recentMaterials.push({ date: d, title: m.title, track: m.track, level: m.level, wordCount: m.wordCount, kind: m.kind });
  }

  const lex = lexiconProfile(reading);
  return {
    today: { date, weekday: ['周日', '周一', '周二', '周三', '周四', '周五', '周六'][day.getDay()], track: TRACK_LABEL[track], isFriday: day.getDay() === 5 },
    progress: {
      startDate: settings.startDate,
      week,
      phase: phase && { n: phase.n, name: phase.name, weeks: `${phase.from}–${phase.to}`, focus: phase.focus, goal: phase.goal },
      phasesReached: phases,
      defaultGrammarThisWeek: phase?.n === 1 ? GRAMMAR_WEEKS[week] : null,
      defaultMaterialLength: phase && lengthBand(week, phase.n),
    },
    attendance: recentDays.map((d) => ({ date: d, checkedIn: !!byDate[d]?.done, minutes: byDate[d]?.minutes || 0, note: byDate[d]?.note || '' })),
    recentPlans,
    recentMaterials,
    grammar: LESSONS.map((l) => {
      const g = grammar[l.id] || {};
      const marks = Object.values(g.marks || {});
      return { id: l.id, title: l.title, done: !!g.done, exercises: l.exercises.length, right: marks.filter((m) => m === 'ok').length, wrong: marks.filter((m) => m === 'bad').length };
    }),
    words: {
      total: words.length,
      known: words.filter((w) => w.known).length,
      learning: words.filter((w) => !w.known).slice(-25).map((w) => ({ word: w.word, meaning: w.meaning, streak: w.streak || 0, added: w.date })),
    },
    vocabulary: {
      note: '来自阅读时标记的生词：每篇材料读的时候点出不认识的词。unknownRatio = 标为生词的词次 / 总词次。',
      distinctWordsKnown: lex.known.size,
      currentlyUnknown: [...lex.unknown].slice(-40),
      sessions: lex.sessions.slice(-8),
    },
    reading: reading.slice(-8).map((r) => {
      const fb = r.summaryAttempts?.at(-1)?.feedback;
      return {
        date: r.date, title: r.title, track: r.track, level: r.level, understood: r.understood, unknownRatio: r.unknownRatio ?? null, hard: r.hard || '',
        summary: r.summary || '', summaryUnderstanding: fb?.understanding.level || null, summaryCorrections: fb ? fb.corrections.map((c) => c.explanation) : [],
      };
    }),
    writing: journal.slice(-6).map((j) => ({ date: j.date, track: j.track, original: j.original, corrected: j.corrected, learned: j.learned })),
    lastReview: reviews.at(-1) || null,
  };
}

function buildPrompt(ctx) {
  const sources = LEVELS.map((l) => `${l.level}（${l.title}，${l.when}）\n  技术：${l.tech.map((s) => s.name).join('；')}\n  日常：${l.daily.map((s) => s.name).join('；')}`).join('\n');
  return `你是一位英语教练，为一位中国软件测试工程师生成【今天】的英语训练计划和阅读材料。

## 学习者
- 目标：顺畅读懂技术文档 / GitHub issue / 技术博客，以及日常文章、帖子、聊天；能用简单英文做工作回复和日常闲聊。不应试、不背难词、不练发音。
- 起点：以前有些基础，但单词和语法基本忘了。
- 工作日每天约 30 分钟，周末休息。周一三五技术线（技术材料 + 工作回复），周二四日常线（日常材料 + 闲聊）；周五额外做周回顾和每周小测。

## 计划框架（必须遵守）
${PHASES.map((p) => `- 阶段 ${p.n}「${p.name}」第 ${p.from}–${p.to} 周：${p.focus}。结束标准：${p.goal}`).join('\n')}
- 阶段 1 默认语法进度：${Object.entries(GRAMMAR_WEEKS).map(([w, ls]) => `第${w}周 ${ls.join('、')}`).join('；')}。周一二学第一课，周三四学第二课，周五复习本周两课。
- 原则：在语境里学词（只记读到的、会再遇到的，抄原句）；语法只为拆长句服务；先读懂再求快（第一遍不查词）；AI 当陪练不当翻译器；漏掉的天不补，照常做当天的内容。
- 各环节分工：语法环节只做"讲解 + 练习"，不要让学习者抄例句或收集例句；从材料里找难句、拆长句属于阅读环节；记生词属于阅读和词汇环节。
- 写作环节给一个具体、有话可说的题目，让学习者用英文表达选择、看法、理由、假设、建议或对某人的回复。阶段 1 写 1–2 句，阶段 2 写 2–4 句，阶段 3 可写一个短段落。技术线可讨论测试或设计中的取舍；日常线可讨论兴趣、生活选择或想象情境。
- 不要布置每日测试进展汇报、工作状态更新、流水账、当天做了什么、日常总结等任务；也不要把这些内容写进 writing.prompt 或写作任务的 title/detail。题目要有明确问题，而不是笼统要求“练习写作”。例如技术线可问“偶发失败的测试，你会先复现还是先看日志？为什么？”；日常线可问“如果能安排一个不用赶时间的周末，你会怎么过？为什么？”。

## 可用资料
语法课（可链接 grammar.html#<id>）：${LESSONS.map((l) => `${l.id} ${l.title}`).join('，')}
阅读来源参考（用来决定写什么风格、改编什么类型的原文）：
${sources}
AI 陪练提示词（在 prompts.html）：${PROMPTS.map((p) => p.title).join('，')}
可链接的页面（task.link 只能用这些值，或 grammar.html#01…#08；不需要链接就留空字符串）：
${Object.entries(PAGES).map(([k, v]) => `- ${k}：${v}`).join('\n')}

## 训练情况（JSON）
${JSON.stringify(ctx, null, 2)}

## 怎么根据训练情况调整
- 最近缺勤多 / 任务常没做完：今天减量，只保留最关键的 2–3 项，总时长可降到 20 分钟。
- 某课语法练习错得多或还没标记学完：放慢进度，先补这一课，不要硬推下一课。
- 生词本里正在学的词：在今天的材料里自然地复现其中 2–4 个。
- 写作日志里反复出现的错误（看 learned 字段）和阅读总结被纠正的点（看 reading 里的 summaryCorrections）：在今天的写作任务里有针对性地练。阅读总结理解"偏离"时，下一篇材料降低难度。
- 参考 lastReview 的"下周调整"。不要和 recentPlans、recentMaterials 重复。

## 阅读材料怎么选（由你来选，学习者不自己挑）
- 材料必须符合今天的线：技术线是测试 / 开发相关的真实场景（改编真实工具文档的说法、GitHub issue、release notes、技术博客段落等）；日常线写地道的英语母语者日常文字（Reddit 帖子和回复、朋友间的消息、生活小博客、评论区等），要用真实的口语表达，不要教科书腔。
- kind：改编自某个真实类型的来源时写 "adapted"，完全原创时写 "original"。sourceName 写改编自哪类来源（如 "Playwright docs · Installation"、"Reddit · r/CasualConversation 风格"），没有就留空。
- 篇幅：默认 ${ctx.progress.defaultMaterialLength || '150–220 词'}，并按词汇量数据调整难度。目标是生词占比（unknownRatio）在 2%–5%：最近 unknownRatio > 8% 或"懂了多少" < 60%，就用更简单的词和更短的句子，篇幅缩短 1/3；最近 unknownRatio < 2% 且懂了 ≥ 85%，就提升难度（更多常见技术词 / 短语动词、稍长的句子）。还没有任何阅读记录时，选一篇中等偏易的材料作为第一次摸底。
- 阶段 1 的材料要有意使用本周的语法点。不要使用 currentlyUnknown 里太多的词（最多复现 2–3 个）。
- glossary：列出 5–8 个这个读者很可能不认识的词或短语，给出这篇文章语境下的中文意思。questions：2–3 道理解题，用简单英文提问，答案用中文写。
- why：用一句中文说明为什么今天选这篇（结合训练情况）。focus：用一句中文说明读的时候注意什么。

## 输出要求
- tasks：今天的任务，按做的顺序排列，3–6 项，总分钟数约 30（减量时可少）。不要包含"打卡"（页面会自动加）。第一项通常是复习生词。阅读任务的 link 用 reading.html#today。id 用简短的英文 kebab-case，且互不重复。title 用中文写一句可执行的话，detail 写具体怎么做（1–3 句中文）。
- material：今天的阅读材料，按上面的要求。text 用空行分段。
- writing：今天的英文表达题目，给一个具体问题或情境，说明要写几句或一个短段落；hints 列出 2–3 个适合表达想法和理由的句型。任务清单中安排一项链接到 writing.html#journal 的写作任务，任务内容与 writing.prompt 一致。
- focus：用一句中文说明今天的重点。
- adjustments：用 1–2 句中文说明根据训练情况做了什么调整；没有调整就写"按计划进行"。`;
}

const GLOSSARY = { type: 'array', items: { type: 'object', additionalProperties: false, required: ['word', 'meaning'], properties: { word: { type: 'string' }, meaning: { type: 'string' } } } };
const QUESTIONS = { type: 'array', items: { type: 'object', additionalProperties: false, required: ['q', 'a'], properties: { q: { type: 'string' }, a: { type: 'string' } } } };

const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['focus', 'adjustments', 'tasks', 'material', 'writing'],
  properties: {
    focus: { type: 'string' },
    adjustments: { type: 'string' },
    tasks: {
      type: 'array', minItems: 2, maxItems: 7,
      items: {
        type: 'object', additionalProperties: false,
        required: ['id', 'title', 'detail', 'minutes', 'link'],
        properties: {
          id: { type: 'string' }, title: { type: 'string' }, detail: { type: 'string' },
          minutes: { type: 'integer', minimum: 1, maximum: 40 }, link: { type: 'string' },
        },
      },
    },
    material: {
      type: 'object', additionalProperties: false,
      required: ['kind', 'title', 'level', 'sourceName', 'why', 'focus', 'text', 'glossary', 'questions'],
      properties: {
        kind: { type: 'string', enum: ['adapted', 'original'] },
        title: { type: 'string' },
        level: { type: 'string', enum: ['L1', 'L2', 'L3', 'L4'] },
        sourceName: { type: 'string' },
        why: { type: 'string' },
        focus: { type: 'string' },
        text: { type: 'string' },
        glossary: GLOSSARY,
        questions: QUESTIONS,
      },
    },
    writing: {
      type: 'object', additionalProperties: false, required: ['prompt', 'hints'],
      properties: { prompt: { type: 'string' }, hints: { type: 'array', items: { type: 'string' } } },
    },
  },
};

// ---------- local AI CLI ----------

async function runAI(prompt, schema) {
  const { output, provider, model, costUsd, durationMs } = await askJson(prompt, schema, {
    timeoutMs: Number(process.env.PRACTISE_AI_TIMEOUT_MS || process.env.PRACTISE_CLAUDE_TIMEOUT_MS || 300000),
  });
  return { output, meta: { provider, model, costUsd, durationMs } };
}

function sanitizeTasks(tasks) {
  const seen = new Set();
  const validLink = (l) => (l && (PAGES[l] || /^grammar\.html#0[1-8]$/.test(l)) ? l : '');
  return tasks
    .filter((t) => !/^check-?in$/i.test(t.id))
    .map((t, i) => {
      let id = String(t.id || `task-${i + 1}`).toLowerCase().replace(/[^a-z0-9-]+/g, '-').replace(/^-|-$/g, '') || `task-${i + 1}`;
      while (seen.has(id)) id += '-x';
      seen.add(id);
      return { ...t, id, link: validLink(t.link) };
    });
}

const REPORT_TASK = /汇报|总结|进展|今天做了什么|今天的一天|今日工作|daily\s*(?:report|update|summary)|status\s*update/i;

function keepWritingExpressive(plan, track) {
  const fallback = track === 'tech'
    ? { prompt: '遇到一个偶发失败的测试时，你会先尝试复现，还是先查看日志？请用英文写 1–2 句，说出你的选择和原因；想多说也可以写一个短段落。', hints: ['I would start with ___ because ___.', 'This could help me ___.'] }
    : { prompt: '如果能安排一个不用赶时间的周末，你最想做哪两件事？为什么？请用英文写 1–2 句；想多说也可以写一个短段落。', hints: ['I would like to ___ because ___.', 'I would also ___ so I can ___.'] };
  const replaced = !plan.writing?.prompt || REPORT_TASK.test(plan.writing.prompt);
  if (replaced) plan.writing = fallback;
  plan.tasks = plan.tasks.map(task => {
    if (!task.link?.startsWith('writing.html') && !task.link?.startsWith('prompts.html')) return task;
    if (!replaced && !REPORT_TASK.test(`${task.title} ${task.detail}`)) return task;
    return task.link.startsWith('prompts.html')
      ? { ...task, title: '和 AI 讨论今日表达题目', detail: '围绕今日写作题目交换看法，试着说出一个理由，再问对方一个问题。' }
      : { ...task, title: '围绕今日题目表达想法', detail: '看今日写作题目，用英文写句子或短段落表达自己的选择和理由。', link: 'writing.html#journal' };
  });
  return plan;
}

async function generate(date) {
  const existing = await readJson(planFile(date), null);
  if (existing) return existing;
  const ctx = await buildContext(date);
  if (!ctx.progress.startDate) throw Object.assign(new Error('还没有设置开始日期'), { status: 400 });
  if (!ctx.progress.week || ctx.progress.week < 1) throw Object.assign(new Error('还没到开始日期'), { status: 400 });
  const { output, meta } = await runAI(buildPrompt(ctx), SCHEMA);
  if (!Array.isArray(output.tasks) || !output.material) throw new Error('AI CLI 没有返回有效的计划');
  const plan = keepWritingExpressive(output, TRACK_BY_DAY[parseYmd(date).getDay()]);
  const track = TRACK_BY_DAY[parseYmd(date).getDay()];
  const common = { date, week: ctx.progress.week, phase: ctx.progress.phase.n, track, generatedAt: new Date().toISOString(), generator: meta };

  const { material, ...rest } = plan;
  // The material is written first; if one was already chosen for today (e.g. by hand), it is kept.
  await createOnce(materialFile(date), { ...common, ...material, wordCount: wordsOf(material.text).length });
  const record = { ...common, ...rest, tasks: sanitizeTasks(rest.tasks) };
  if (!(await createOnce(planFile(date), record))) return readJson(planFile(date), record);
  return record;
}

// ---------- feedback on a reading summary and its hardest sentence ----------

const FEEDBACK_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['understanding', 'corrections', 'corrected', 'better', 'tip', 'sentenceAnalysis'],
  properties: {
    understanding: {
      type: 'object', additionalProperties: false, required: ['level', 'comment'],
      properties: { level: { type: 'string', enum: ['准确', '基本准确', '偏离'] }, comment: { type: 'string' } },
    },
    corrections: {
      type: 'array',
      items: {
        type: 'object', additionalProperties: false, required: ['original', 'corrected', 'explanation'],
        properties: { original: { type: 'string' }, corrected: { type: 'string' }, explanation: { type: 'string' } },
      },
    },
    corrected: { type: 'string' },
    better: { type: 'string' },
    tip: { type: 'string' },
    sentenceAnalysis: {
      type: 'object', additionalProperties: false,
      required: ['sentence', 'mainClause', 'parts', 'naturalMeaning', 'readingTip'],
      properties: {
        sentence: { type: 'string' }, mainClause: { type: 'string' },
        parts: { type: 'array', items: { type: 'object', additionalProperties: false,
          required: ['text', 'role', 'explanation'], properties: {
            text: { type: 'string' }, role: { type: 'string' }, explanation: { type: 'string' },
          } } },
        naturalMeaning: { type: 'string' }, readingTip: { type: 'string' },
      },
    },
  },
};

function feedbackPrompt(record, material, summary, previous) {
  return `你是一位耐心的英语老师。学习者是中国软件测试工程师，英语基础薄弱，正在练阅读理解和拆句。请点评英文总结，并解析他摘出的最难一句。

${material ? `## 材料（${material.level}，${material.wordCount} 词）
标题：${material.title}
${material.text}` : `## 材料
标题：${record.title}（没有原文，只评价语言，不评价理解）`}

## 学习者的英文总结
${summary || '（这次没有写英文总结）'}
## 学习者摘出的最难一句
${record.hard || '（这次没有摘句子）'}
${previous.length ? `\n## 之前的版本和反馈（这次是改写后再评）\n${previous.map((a, i) => `第 ${i + 1} 版：${a.summary}\n当时的提示：${a.feedback.tip}`).join('\n')}\n` : ''}
## 要求
- understanding：对照原文判断总结有没有抓住主要意思。level 只能是 准确 / 基本准确 / 偏离；comment 用 1–2 句中文说明，偏离时指出原文真正讲的是什么。没有原文时 level 写"基本准确"，comment 写"没有原文，只看语言"。
- corrections：逐处列出语法、用词、搭配、拼写、标点上的错误。original 是原文片段，corrected 是改后的片段，explanation 用简短中文解释为什么（例如"三单动词要加 s"）。没有错误就返回空数组。不要为了"更好听"而列出本来没错的地方。
- corrected：在学习者原句基础上做最小改动的正确版本（保留他的意思和用词）。
- better：一个更地道、也更完整的总结，用他这个水平能看懂的简单词，1–2 句。
- tip：用一句中文说出这次最值得记住的一个点。
- 如果没有英文总结：understanding.level 写"基本准确"，comment 写"未提供英文总结，本次只解析难句"；corrections 返回空数组，corrected、better、tip 返回空字符串。不要把空总结当错误。
- sentenceAnalysis：如果摘了难句，sentence 保留原句；mainClause 用中文指出主语、谓语和核心意思；parts 按阅读顺序拆出 2–6 个片段，分别写出原文片段 text、语法作用 role、中文解释 explanation；naturalMeaning 给自然的整句中文意思；readingTip 指出读懂这句最关键的一个结构。结合材料上下文解释，不要编造句中没有的成分。没有原文时可只根据摘句本身解析，并指出上下文不确定处。
- 如果没有摘句子：sentenceAnalysis 的各字符串留空，parts 返回空数组。不要凭空编造难句。
- 语气鼓励但直接，不要客套。`;
}

async function summaryFeedback(id, summary) {
  const reading = await data('reading', []);
  const rec = reading.find((r) => r.id === id);
  if (!rec) throw Object.assign(new Error('找不到这条阅读记录'), { status: 404 });
  summary = summary || rec.summary || '';
  if (!summary && !rec.hard) throw Object.assign(new Error('请先写英文总结或摘出最难一句'), { status: 400 });
  const material = rec.planDate ? await readJson(materialFile(rec.planDate), null) : null;
  const previous = rec.summaryAttempts || [];
  const { output, meta } = await runAI(feedbackPrompt(rec, material, summary, previous), FEEDBACK_SCHEMA);
  if (rec.hard && !output.sentenceAnalysis?.mainClause) throw new Error('AI 没有返回难句解析，请重试');

  // Re-read before writing so changes made while the CLI ran aren't lost.
  const fresh = await data('reading', []);
  const target = fresh.find((r) => r.id === id);
  if (!target) throw Object.assign(new Error('这条阅读记录已被删除'), { status: 404 });
  target.summary = summary;
  target.summaryAttempts = [...(target.summaryAttempts || []), { summary, at: new Date().toISOString(), feedback: output, generator: meta }];
  await writeFile(join(DATA, 'reading.json'), JSON.stringify(fresh, null, 2) + '\n');
  return target;
}

// ---------- in-page AI coaching ----------

const COACH_SCHEMA = {
  type: 'object', additionalProperties: false, required: ['reply', 'suggestedRevision'],
  properties: { reply: { type: 'string' }, suggestedRevision: { type: 'string' } },
};

function coachPrompt(template, values, messages) {
  let index = 0;
  const exercise = template.text.replace(/\{\{([^|}]+)(?:\|([^}]*))?\}\}/g, (_, name, hint) => {
    const value = String(values[index++] || '').trim().slice(0, 6000) || hint?.split(' / ')[0] || '';
    return value || `（学习者尚未提供「${name}」）`;
  });
  const history = messages.map(m => `${m.role === 'user' ? '学习者' : 'AI'}：${m.content}`).join('\n\n');
  return `你是英语阅读与写作陪练，学习者有一点旧基础，希望能读懂技术和日常英语，并用简单英文回复。按照下面的练习要求直接进行当前这一轮互动。用清楚、简短、适合初学者的语言；需要解释错误时用中文。不要声称运行了工具。\n\n## 本次练习\n${exercise}\n\n## 已有对话（只作上下文）\n${history || '（尚未开始）'}\n\n## 开场与缺失内容\n如果学习者没有写第一句，你主动开启话题。练习中的某项内容若标为尚未提供，而最新的学习者消息正好提供了这项内容，就用那条消息完成练习；否则先简短询问学习者，请他提供所需内容。不要对尚未提供的句子、段落或词编造点评。\n\n## 输出\nreply：本轮给学习者看的回复。若练习要求对话，就继续对话；若要求点评，就直接给具体反馈。不要重复整段历史。\nsuggestedRevision：只有「改我写的句子」练习且已收到原文时才填写学习者原文的最小改动正确版本；其他练习写空字符串。只返回 JSON。`;
}

async function coach(input) {
  if (!input || typeof input !== 'object') throw Object.assign(new Error('练习参数格式不正确'), { status: 400 });
  const template = PROMPTS.find(p => p.id === input.templateId);
  if (!template) throw Object.assign(new Error('请选择有效的陪练项目'), { status: 400 });
  if (!Array.isArray(input.values) || input.values.length > 8) throw Object.assign(new Error('练习参数格式不正确'), { status: 400 });
  if (!Array.isArray(input.messages) || input.messages.length > 40) throw Object.assign(new Error('对话过长，请开始新练习'), { status: 400 });
  const messages = input.messages.map(m => ({ role: m.role, content: String(m.content || '').slice(0, 4000) }));
  if (messages.some(m => !['user', 'assistant'].includes(m.role) || !m.content.trim()) || (messages.length && messages.at(-1).role !== 'user'))
    throw Object.assign(new Error('对话格式不正确'), { status: 400 });
  const result = await runAI(coachPrompt(template, input.values, messages), COACH_SCHEMA);
  if (!result.output?.reply?.trim()) throw new Error('AI 没有返回有效回复');
  return { reply: result.output.reply, suggestedRevision: result.output.suggestedRevision || '', ...result.meta };
}

// ---------- routes ----------

export async function handle(req, res, action, url, { send, sendJson, readBody }) {
  const dateParam = () => {
    const date = url.searchParams.get('date') || ymd();
    return DATE.test(date) ? date : null;
  };
  if ((action === 'plan' || action === 'material') && req.method === 'GET') {
    const date = dateParam();
    if (!date) return send(res, 400, 'bad date');
    let body = await readJson(action === 'plan' ? planFile(date) : materialFile(date), null);
    // Plans generated before materials were split out carry their reading inline.
    if (!body && action === 'material') {
      const p = await readJson(planFile(date), null);
      if (p?.reading) body = { date, track: p.track, kind: 'original', sourceName: '', why: '', focus: '', ...p.reading, wordCount: wordsOf(p.reading.text).length };
    }
    return sendJson(res, 200, body);
  }
  if (action === 'plan' && req.method === 'POST') {
    const date = ymd();
    if (!isWorkday(parseYmd(date))) return sendJson(res, 400, { error: '周末休息，不生成计划' });
    if (!inflight.has(date)) inflight.set(date, generate(date).finally(() => inflight.delete(date)));
    try {
      return sendJson(res, 200, await inflight.get(date));
    } catch (e) {
      return sendJson(res, e.status || 502, { error: e.message });
    }
  }
  if (action === 'coach' && req.method === 'POST') {
    let body;
    try { body = JSON.parse(await readBody(req)); } catch { return sendJson(res, 400, { error: 'invalid JSON' }); }
    try { return sendJson(res, 200, await coach(body)); }
    catch (e) { return sendJson(res, e.status || 502, { error: e.message }); }
  }
  if (action === 'summary-feedback' && req.method === 'POST') {
    let body;
    try { body = JSON.parse(await readBody(req)); } catch { return sendJson(res, 400, { error: 'invalid JSON' }); }
    const summary = String(body.summary || '').trim();
    if (!body.id) return sendJson(res, 400, { error: '缺少记录 id' });
    try {
      return sendJson(res, 200, await summaryFeedback(String(body.id), summary));
    } catch (e) {
      return sendJson(res, e.status || 502, { error: e.message });
    }
  }
  if (action === 'plans' && req.method === 'GET') {
    let files = [];
    try { files = (await readdir(PLANS)).filter((f) => /^\d{4}-\d{2}-\d{2}\.json$/.test(f)); } catch {}
    const list = [];
    for (const f of files.sort().reverse()) {
      const p = await readJson(join(PLANS, f), null);
      if (p) list.push({ date: p.date, week: p.week, track: p.track, focus: p.focus });
    }
    return sendJson(res, 200, list);
  }
  return send(res, 404, 'not found');
}
